/* Mathematik – Grundlagen – version allemande, générée par outils/traduction.js depuis data.js (mêmes épreuves, même ordre). a[0] = richtige Antwort. */
window.OBJ = [{"code":"Mod. 1a","t":"Längen und Massen","g":"Längen und Massen mit den Einheitentabellen umrechnen","col":"teal","ic":"ruler","ch":[{"k":"qcm","img":"longueurs","q":"Was macht man in der Längentabelle bei jedem Schritt zu einer kleineren Einheit (nach rechts)?","a":["Man multipliziert mit 10","Man multipliziert mit 100","Man dividiert durch 10","Man multipliziert mit 1’000"],"ex":"km → hm → dam → m → dm → cm → mm: jeder Schritt nach rechts = × 10, jeder Schritt nach links = ÷ 10.","ref":"Modul 1 · Längen umrechnen"},{"k":"num","q":"Rechnen Sie 3.5 km in Meter um.","n":3500,"tol":0,"u":"m","ex":"km → m = 3 Schritte nach rechts: 3.5 × 10 × 10 × 10 = 3’500 m.","ref":"Modul 1 · Längen umrechnen"},{"k":"num","q":"Rechnen Sie 2.4 m in Zentimeter um.","n":240,"tol":0,"u":"cm","ex":"m → cm = 2 Schritte nach rechts: 2.4 × 100 = 240 cm.","ref":"Modul 1 · Längen umrechnen"},{"k":"num","q":"Rechnen Sie 1’250 mm in Zentimeter um.","n":125,"tol":0,"u":"cm","ex":"mm → cm = 1 Schritt nach links: 1’250 ÷ 10 = 125 cm.","ref":"Modul 1 · Längen umrechnen"},{"k":"qcm","q":"Eine EUR-Palette ist 1’200 mm lang. Wie viel sind das in Metern?","a":["1.2 m","12 m","0.12 m","120 m"],"ex":"mm → m = 3 Schritte nach links: 1’200 ÷ 1’000 = 1.2 m.","ref":"Modul 1 · Längen umrechnen"},{"k":"case","s":"Der Lagerist der Stockalp AG stellt Kartons von 35 cm Breite nebeneinander auf einen 4.2 m langen Fachboden eines Regals.","q":"Wie viele Kartons haben auf der Länge des Fachbodens Platz?","a":["12 Kartons","120 Kartons","14 Kartons","1 Karton"],"ex":"Alles in dieselbe Einheit: 4.2 m = 420 cm. 420 ÷ 35 = 12 Kartons.","ref":"Modul 1 · Längen umrechnen"},{"k":"order","q":"Ordnen Sie diese Längeneinheiten von der grössten zur kleinsten.","a":["km","dam","m","cm","mm"],"ex":"Reihenfolge der Tabelle: km, hm, dam, m, dm, cm, mm.","ref":"Modul 1 · Längen umrechnen"},{"k":"match","q":"Ordnen Sie jeder Einheit ihre Entsprechung zu.","p":[["1 km","1’000 m"],["1 m","100 cm"],["1 cm","10 mm"],["1 dam","10 m"]],"ex":"Jeder Schritt der Tabelle ist × 10: 1 m = 10 dm = 100 cm = 1’000 mm.","ref":"Modul 1 · Längen umrechnen"},{"k":"tf","q":"Um 5 mm in Meter umzurechnen, multipliziert man mit 1’000.","v":false,"ex":"Falsch: mm → m geht zu einer grösseren Einheit, also dividiert man: 5 ÷ 1’000 = 0.005 m.","ref":"Modul 1 · Längen umrechnen"},{"k":"tf","q":"1 hg (Hektogramm) entspricht 10 g.","v":false,"ex":"Falsch: 1 hg = 100 g. 1 dag (Dekagramm) entspricht 10 g.","ref":"Modul 1 · Massen umrechnen"},{"k":"qcm","q":"Wie viele Kilogramm hat 1 Tonne?","a":["1’000 kg","100 kg","10 kg","10’000 kg"],"ex":"1 t = 1’000 kg. In der Tabelle t, q, kg: 1 t = 10 q und 1 q = 100 kg.","ref":"Modul 1 · Massen umrechnen"},{"k":"qcm","q":"Wie viel ist ein Doppelzentner (q)?","a":["100 kg","10 kg","1’000 kg","50 kg"],"ex":"Der Doppelzentner steht zwischen Tonne und Kilogramm: 1 q = 100 kg.","ref":"Modul 1 · Massen umrechnen"},{"k":"num","q":"Rechnen Sie 2.75 t in Kilogramm um.","n":2750,"tol":0,"u":"kg","ex":"t → kg: × 1’000. 2.75 × 1’000 = 2’750 kg.","ref":"Modul 1 · Massen umrechnen"},{"k":"num","q":"Rechnen Sie 2’500 dag in Kilogramm um.","n":25,"tol":0,"u":"kg","ex":"dag → kg = 2 Schritte nach links (dag → hg → kg): 2’500 ÷ 10 ÷ 10 = 25 kg. Häufiger Fehler: 250 kg (nur ein Schritt).","ref":"Modul 1 · Massen umrechnen"},{"k":"case","s":"Ein Lastwagen von TransRhône liefert drei Posten: 600 kg Schrauben, 1.4 t Bleche und 2’500 dag Etiketten. Der Chauffeur muss die Gesamtmasse auf dem Lieferschein notieren.","q":"Welche Gesamtmasse muss er eintragen?","a":["2’025 kg","2’250 kg","2’000 kg","4’500 kg"],"ex":"Alles in kg umrechnen: 600 kg + 1’400 kg + 25 kg = 2’025 kg. 2’500 dag = 25 kg, nicht 250 kg.","ref":"Modul 1 · Massen umrechnen"},{"k":"fill","q":"Um Gramm in Kilogramm umzurechnen, ___ man durch 1’000.","a":["dividiert","multipliziert","addiert","subtrahiert"],"ex":"g → kg: zu einer grösseren Einheit dividiert man. 3’400 g = 3.4 kg.","ref":"Modul 1 · Massen umrechnen"},{"k":"sort","q":"Ordnen Sie jede Masse zu: weniger als 1 kg oder 1 kg und mehr?","c":["Weniger als 1 kg","1 kg und mehr"],"it":[["950 g",0],["12 hg",1],["80 dag",0],["0.001 t",1],["1’500’000 mg",1],["9 hg",0]],"ex":"12 hg = 1.2 kg; 80 dag = 0.8 kg; 0.001 t = 1 kg; 1’500’000 mg = 1.5 kg; 9 hg = 0.9 kg.","ref":"Modul 1 · Massen umrechnen"},{"k":"odd","q":"Finden Sie den Ausreisser: Welche Länge ist NICHT gleich 1.5 m?","a":["15 cm","150 cm","1’500 mm","15 dm"],"ex":"1.5 m = 15 dm = 150 cm = 1’500 mm. 15 cm sind nur 0.15 m.","ref":"Modul 1 · Längen umrechnen"},{"k":"case","s":"Ein Gabelstapler hat eine Tragfähigkeit von 1.2 t. Der Staplerfahrer muss eine Palette von 850 kg heben, auf die man 3 Kartons zu 120 kg gestellt hat.","q":"Kann er diese Last heben?","a":["Nein: 1’210 kg, Überschreitung um 10 kg","Ja: 1’210 kg, es bleiben 10 kg","Ja: 850 kg liegen unter 1.2 t","Nein: 1’210 kg überschreiten 12 t"],"ex":"1.2 t = 1’200 kg. 850 + 3 × 120 = 1’210 kg > 1’200 kg: Überschreitung um 10 kg. Ein Karton muss weg.","ref":"Modul 1 · Massen umrechnen"},{"k":"case","s":"Am Versandplatz verpackt ein Kommissionierer 18 gleiche Pakete zu 750 g für denselben Kunden.","q":"Wie gross ist die Gesamtmasse der Sendung?","a":["13.5 kg","135 kg","1.35 kg","13’500 kg"],"ex":"18 × 750 g = 13’500 g = 13.5 kg (÷ 1’000).","ref":"Modul 1 · Massen umrechnen"},{"k":"multi","q":"Welche Massen sind genau 2 kg?","good":["2’000 g","20 hg","200 dag","2’000’000 mg"],"bad":["0.2 t","20’000 mg"],"ex":"2 kg = 20 hg = 200 dag = 2’000 g = 2’000’000 mg. 0.2 t = 200 kg; 20’000 mg = 20 g.","ref":"Modul 1 · Massen umrechnen"},{"k":"case","s":"Um ins Nebenlager zu gelangen, fährt der Staplerfahrer 0.6 km auf der Werkstrasse und dann noch 450 m im Hof.","q":"Welche Strecke legt er zurück?","a":["1’050 m","1’050 km","456 m","0.105 km"],"ex":"Vor dem Addieren umrechnen: 0.6 km = 600 m. 600 + 450 = 1’050 m.","ref":"Modul 1 · Längen umrechnen"},{"k":"case","s":"Zwischen der Warenannahme und der Lagerzone liegen 85 m. Heute Morgen ist der Staplerfahrer 12-mal hin und zurück gefahren.","q":"Welche Strecke hat er zurückgelegt?","a":["2.04 km","1.02 km","20.4 km","0.204 km"],"ex":"Hin und zurück = 2 × 85 = 170 m. 12 × 170 = 2’040 m = 2.04 km.","ref":"Modul 1 · Längen umrechnen"},{"k":"case","s":"Ein Lastwagen muss unter einem 3.8 m hohen Lagertor durchfahren. Die Ladung: 3 gestapelte Paletten zu je 1’350 mm, auf der Ladefläche.","q":"Ist die Ladung (ohne Lastwagen) schon höher als das Tor?","a":["Ja: 4.05 m > 3.8 m","Nein: 4.05 m < 3.8 m","Nein: 1’350 mm < 3.8 m","Ja: 4’050 m > 3.8 m"],"ex":"3 × 1’350 = 4’050 mm = 4.05 m. Das ist mehr als 3.8 m: Man muss abstapeln.","ref":"Modul 1 · Längen umrechnen"},{"k":"case","s":"Für einen Auftrag wurden 250 Rollen Stretchfolie zu je 2.4 kg bereitgestellt. Der Transporteur verlangt die Masse in Tonnen.","q":"Welche Masse melden Sie?","a":["0.6 t","6 t","0.06 t","60 t"],"ex":"250 × 2.4 = 600 kg. 600 ÷ 1’000 = 0.6 t.","ref":"Modul 1 · Massen umrechnen"},{"k":"case","s":"Der Lieferschein nennt drei Pakete: 12.5 kg, 8’400 g und 95 hg. Sie müssen die Gesamtmasse prüfen.","q":"Wie gross ist die Gesamtmasse?","a":["30.4 kg","125.9 kg","3.04 kg","304 kg"],"ex":"8’400 g = 8.4 kg; 95 hg = 9.5 kg. 12.5 + 8.4 + 9.5 = 30.4 kg.","ref":"Modul 1 · Massen umrechnen"},{"k":"num","q":"Rechnen Sie 4’500 kg in Doppelzentner (q) um.","n":45,"tol":0,"u":"q","ex":"kg → q: ÷ 100. 4’500 ÷ 100 = 45 q.","ref":"Modul 1 · Massen umrechnen"},{"k":"tf","q":"1 dam (Dekameter) entspricht 10 m.","v":true,"ex":"Richtig: km, hm, dam, m. 1 dam = 10 m; 1 hm = 100 m.","ref":"Modul 1 · Längen umrechnen"}]},{"code":"Mod. 1b","t":"Kraft und Gewicht","g":"Das Gewicht (Kraft in Newton) einer Last aus ihrer Masse berechnen, und umgekehrt","col":"indigo","ic":"weight","ch":[{"k":"qcm","q":"In welcher Einheit gibt man eine Kraft an, zum Beispiel das Gewicht einer Last?","a":["In Newton (N)","In Kilogramm (kg)","In Joule (J)","In Pascal (Pa)"],"ex":"Die Masse wird in kg angegeben; das Gewicht ist eine Kraft und wird in Newton (N) angegeben.","ref":"Modul 1 · Kraft und Gewicht"},{"k":"tf","q":"Die Masse (in kg) und das Gewicht (in N) sind zwei verschiedene Grössen.","v":true,"ex":"Richtig: Die Masse ist die Stoffmenge (kg); das Gewicht ist die Kraft, die diese Masse ausübt (N).","ref":"Modul 1 · Kraft und Gewicht"},{"k":"fill","q":"Das Gewicht einer Last berechnet man mit der Formel F = m × ___ (in N/kg).","a":["9.81","0.981","98.1","3.6"],"ex":"F (N) = m (kg) × 9.81. In der Praxis rundet man für Schätzungen oft auf 10.","ref":"Modul 1 · Kraft und Gewicht"},{"k":"num","q":"Mit dem praktischen Rundungswert g ≈ 10 N/kg: Wie schwer ist eine Kiste von 50 kg?","n":500,"tol":0,"u":"N","ex":"50 × 10 = 500 N (genau: 50 × 9.81 = 490.5 N).","ref":"Modul 1 · Kraft und Gewicht"},{"k":"qcm","q":"Wie gross ist das genaue Gewicht eines Kartons von 20 kg (g = 9.81 N/kg)?","a":["196.2 N","1’962 N","2.04 N","19.62 N"],"ex":"20 × 9.81 = 196.2 N.","ref":"Modul 1 · Kraft und Gewicht"},{"k":"num","q":"Wie viele Newton sind 1 kN?","n":1000,"tol":0,"u":"N","ex":"Kilo = 1’000: 1 kN = 1’000 N.","ref":"Modul 1 · Kraft und Gewicht"},{"k":"num","q":"Rechnen Sie 2.5 kN in Newton um.","n":2500,"tol":0,"u":"N","ex":"2.5 × 1’000 = 2’500 N.","ref":"Modul 1 · Kraft und Gewicht"},{"k":"qcm","q":"Eine Last übt ein Gewicht von 981 N aus. Wie gross ist ihre Masse?","a":["100 kg","98.1 kg","9’624 kg","10 kg"],"ex":"m = F ÷ 9.81 = 981 ÷ 9.81 = 100 kg. Häufiger Fehler: durch 10 statt durch 9.81 teilen, das ergibt 98.1 kg.","ref":"Modul 1 · Kraft und Gewicht"},{"k":"case","s":"Der Handhubwagen der Werkstatt hat eine Tragfähigkeit von 2’000 kg. Der Kraftmesser zeigt, dass die zu bewegende Palette eine Kraft von 17’658 N ausübt.","q":"Kann der Hubwagen sie bewegen?","a":["Ja: 1’800 kg, es bleiben 200 kg","Nein: 17’658 kg überschreiten 2’000 kg","Ja: nur 176.58 kg","Nein: 1’800 kg überschreiten 2’000 kg"],"ex":"m = 17’658 ÷ 9.81 = 1’800 kg ≤ 2’000 kg: Das ist möglich, mit 200 kg Reserve.","ref":"Modul 1 · Kraft und Gewicht"},{"k":"case","s":"Ein Fachboden trägt höchstens 3 kN. Ein Kommissionierer will 4 Kartons zu 80 kg darauf stellen. Er schätzt das Gewicht mit g ≈ 10 N/kg.","q":"Kann er die 4 Kartons abstellen?","a":["Nein: 3’200 N überschreiten 3’000 N","Ja: 320 N bleiben unter 3 kN","Ja: 3’200 N bleiben unter 3 kN","Nein: 320 kg überschreiten 3 kg"],"ex":"4 × 80 = 320 kg → 320 × 10 = 3’200 N = 3.2 kN > 3 kN. Höchstens 3 Kartons sind erlaubt.","ref":"Modul 1 · Kraft und Gewicht"},{"k":"match","q":"Ordnen Sie jeder Masse ihr ungefähres Gewicht zu (g ≈ 10 N/kg).","p":[["1 kg","≈ 10 N"],["50 kg","≈ 500 N"],["100 kg","≈ 1 kN"],["1 t","≈ 10 kN"]],"ex":"Gewicht ≈ Masse × 10: 1 t = 1’000 kg → ≈ 10’000 N = 10 kN.","ref":"Modul 1 · Kraft und Gewicht"},{"k":"order","q":"Bringen Sie die Berechnung des Gewichts einer Last in Tonnen in die richtige Reihenfolge.","a":["Die Masse in kg umrechnen","Mit 9.81 multiplizieren","Das Ergebnis in N schreiben","Falls nötig in kN umrechnen (÷ 1’000)"],"ex":"Beispiel: 1.5 t = 1’500 kg; 1’500 × 9.81 = 14’715 N = 14.715 kN.","ref":"Modul 1 · Kraft und Gewicht"},{"k":"sort","q":"Ordnen Sie jeden Wert zu: Masse oder Kraft (Gewicht)?","c":["Masse","Kraft (Gewicht)"],"it":[["1.2 t",0],["450 kg",0],["12 kN",1],["981 N",1],["750 g",0],["4’000 N",1]],"ex":"t, kg und g sind Masseneinheiten; N und kN sind Krafteinheiten.","ref":"Modul 1 · Kraft und Gewicht"},{"k":"odd","q":"Finden Sie den Ausreisser: Welche ist KEINE Krafteinheit?","a":["kg","N","kN","daN"],"ex":"Das Kilogramm ist eine Masseneinheit. N, kN und daN (Dekanewton) messen eine Kraft.","ref":"Modul 1 · Kraft und Gewicht"},{"k":"tf","q":"Auf dem Mond ist die Masse eines Pakets kleiner als auf der Erde.","v":false,"ex":"Falsch: Die Masse ändert sich nicht. Es ändert sich das Gewicht (die Kraft), weil die Anziehung schwächer ist.","ref":"Modul 1 · Kraft und Gewicht"},{"k":"num","q":"Mit g ≈ 10 N/kg: Wie schwer ist eine Kiste von 1.5 t, in kN?","n":15,"tol":0,"u":"kN","ex":"1.5 t = 1’500 kg → 1’500 × 10 = 15’000 N = 15 kN.","ref":"Modul 1 · Kraft und Gewicht"},{"k":"qcm","q":"Wie gross ist das genaue Gewicht einer Palette von 600 kg?","a":["5’886 N","6’000 N","61.2 N","588.6 N"],"ex":"600 × 9.81 = 5’886 N. 6’000 N ist die Schätzung mit g ≈ 10.","ref":"Modul 1 · Kraft und Gewicht"},{"k":"case","s":"Ein Flaschenzug der Werkstatt trägt höchstens 5 kN. Der Mechaniker muss einen Motor von 450 kg anheben, um ihn auf eine Palette zu stellen.","q":"Eignet sich der Flaschenzug?","a":["Ja: 4’414.5 N < 5’000 N","Nein: 4’414.5 N > 5’000 N","Nein: 450 kg > 5 kg","Ja: 45.9 N < 5 kN"],"ex":"F = 450 × 9.81 = 4’414.5 N, also 4.41 kN: Das liegt unter der Grenze von 5 kN.","ref":"Modul 1 · Kraft und Gewicht"},{"k":"case","s":"Das Datenblatt eines Hebegeräts nennt eine maximale Hubkraft von 25 kN. Der Teamleiter will die maximale Masse kennen.","q":"Welche Masse darf man höchstens heben?","a":["Etwa 2’548 kg","Etwa 245 kg","Etwa 25 kg","Etwa 245’250 kg"],"ex":"25 kN = 25’000 N. m = 25’000 ÷ 9.81 ≈ 2’548 kg (etwa 2.5 t).","ref":"Modul 1 · Kraft und Gewicht"},{"k":"case","s":"Ein Kollege berechnet das Gewicht einer Palette von 300 kg und schreibt auf sein Blatt: «300 ÷ 9.81 = 30.6 N».","q":"Was antworten Sie ihm?","a":["Falsch: Man muss multiplizieren, 2’943 N","Richtig: Das Gewicht beträgt 30.6 N","Falsch: Man muss durch 10 teilen","Richtig, aber in kg schreiben"],"ex":"Gewicht = Masse × 9.81 = 300 × 9.81 = 2’943 N. Man dividiert nur, um von einer Kraft auf eine Masse zu kommen.","ref":"Modul 1 · Kraft und Gewicht"},{"k":"num","q":"Eine Last wiegt 3’000 N. Mit g ≈ 10 N/kg: Wie gross ist ihre Masse?","n":300,"tol":0,"u":"kg","ex":"m ≈ 3’000 ÷ 10 = 300 kg (genau: 3’000 ÷ 9.81 ≈ 305.8 kg).","ref":"Modul 1 · Kraft und Gewicht"},{"k":"multi","q":"Welche Aussagen sind richtig?","good":["Das Gewicht wird in Newton angegeben","1 kg wiegt etwa 10 N","1 kN = 1’000 N"],"bad":["1 N = 1 kg","Das Gewicht berechnet man, indem man die Masse durch 9.81 teilt"],"ex":"Gewicht (N) = Masse (kg) × 9.81; 1 kg wiegt 9.81 N, nicht 1 N.","ref":"Modul 1 · Kraft und Gewicht"},{"k":"case","s":"Jede Ebene eines Regals trägt 5 kN. Dort lagern Kartons zu 40 kg. Für die Berechnung verwendet der Betrieb g ≈ 10 N/kg.","q":"Wie viele Kartons darf man höchstens pro Ebene abstellen?","a":["12 Kartons","13 Kartons","125 Kartons","1 Karton"],"ex":"1 Karton ≈ 40 × 10 = 400 N. 5’000 ÷ 400 = 12.5 → man rundet ab: 12 Kartons.","ref":"Modul 1 · Kraft und Gewicht"},{"k":"qcm","q":"Welcher Masse entspricht eine Kraft von 4’905 N?","a":["500 kg","48’118 kg","490.5 kg","50 kg"],"ex":"m = 4’905 ÷ 9.81 = 500 kg.","ref":"Modul 1 · Kraft und Gewicht"},{"k":"case","s":"Ein Brückenkran ist bis 2 t zugelassen. Der Sensor der hängenden Last zeigt 22 kN an.","q":"Ist die Last erlaubt?","a":["Nein: etwa 2’243 kg > 2’000 kg","Ja: etwa 224 kg < 2’000 kg","Ja: 22 kN bleiben unter der Grenze von 2 t","Nein: 22 kN entsprechen 22 t"],"ex":"22 kN = 22’000 N. m = 22’000 ÷ 9.81 ≈ 2’243 kg: Das ist mehr als 2’000 kg. Man hebt nicht.","ref":"Modul 1 · Kraft und Gewicht"},{"k":"case","s":"Ein Container von 1’200 kg steht auf dem Boden einer Ladeplattform. Der Sicherheitsverantwortliche will die ausgeübte Kraft in kN.","q":"Welche Kraft übt der Container aus?","a":["11.77 kN","11’772 kN","122.32 kN","1.22 kN"],"ex":"1’200 × 9.81 = 11’772 N = 11.77 kN.","ref":"Modul 1 · Kraft und Gewicht"}]},{"code":"Mod. 1c","t":"Prozentrechnen","g":"Einen Anteil, einen Prozentsatz und einen Wert nach Erhöhung oder Rabatt berechnen","col":"violet","ic":"percent","ch":[{"k":"qcm","q":"Welchem Bruch entsprechen 25 %?","a":["1/4","1/25","2/5","1/2"],"ex":"25 % = 25/100 = 1/4.","ref":"Modul 1 · Prozentrechnen"},{"k":"num","q":"Berechnen Sie 15 % von 400 Paketen.","n":60,"tol":0,"u":"Pakete","ex":"Anteil = Total × Prozentsatz ÷ 100 = 400 × 15 ÷ 100 = 60 Pakete.","ref":"Modul 1 · Prozentrechnen"},{"k":"num","q":"Berechnen Sie 10 % von CHF 2’500.","n":250,"tol":0,"u":"CHF","ex":"2’500 × 10 ÷ 100 = CHF 250.","ref":"Modul 1 · Prozentrechnen"},{"k":"num","q":"Von 80 Aufträgen werden 12 verspätet geliefert. Wie viel Prozent Verspätungen sind das?","n":15,"tol":0,"u":"%","ex":"Prozentsatz = Anteil ÷ Total × 100 = 12 ÷ 80 × 100 = 15 %.","ref":"Modul 1 · Prozentrechnen"},{"k":"fill","q":"Prozentsatz (%) = Anteil ÷ ___ × 100.","a":["Total","Anteil","Prozentsatz","Rabatt"],"ex":"Man teilt den Anteil durch das Total und multipliziert dann mit 100.","ref":"Modul 1 · Prozentrechnen"},{"k":"qcm","q":"Wie schreibt man 4.5 % als Dezimalzahl?","a":["0.045","0.45","4.5","0.0045"],"ex":"4.5 % = 4.5 ÷ 100 = 0.045. In einer Antwort schreibt man den Satz mit dem Zeichen %: 4.5 %.","ref":"Modul 1 · Prozentrechnen"},{"k":"match","q":"Ordnen Sie jedem Prozentsatz seinen Wert zu.","p":[["50 %","1/2"],["25 %","1/4"],["10 %","0.1"],["75 %","3/4"]],"ex":"Prozent ÷ 100 = Dezimalzahl.","ref":"Modul 1 · Prozentrechnen"},{"k":"case","s":"Logibois bestellt Material für CHF 3’000. Der Lieferant gewährt 12 % Rabatt und verrechnet dann CHF 120 Transportkosten.","q":"Wie hoch ist der zu zahlende Betrag?","a":["CHF 2’760.00","CHF 2’640.00","CHF 2’745.60","CHF 3’108.00"],"ex":"Zuerst der Rabatt: 3’000 × 0.88 = 2’640. Dann die Kosten: 2’640 + 120 = CHF 2’760.00.","ref":"Modul 3 · Aufgaben Serie 2"},{"k":"num","q":"Wie hoch ist der Rabatt von 12 % auf einer Bestellung von CHF 3’000?","n":360,"tol":0,"u":"CHF","ex":"3’000 × 12 ÷ 100 = CHF 360.","ref":"Modul 3 · Aufgaben Serie 2"},{"k":"case","s":"Das Lager enthielt 1’200 Kartons eines Artikels. Während der Woche wurden 35 % des Bestands versandt.","q":"Wie viele Kartons bleiben übrig?","a":["780 Kartons","420 Kartons","1’165 Kartons","835 Kartons"],"ex":"Versandt: 1’200 × 0.35 = 420. Rest: 1’200 − 420 = 780 Kartons (oder 1’200 × 0.65).","ref":"Modul 1 · Prozentrechnen"},{"k":"case","s":"Bei der Inventur stellt der Lagerist 6 Abweichungen bei 240 kontrollierten Lagerplätzen fest. Der Verantwortliche will die Fehlerquote.","q":"Wie hoch ist die Fehlerquote?","a":["2.5 %","0.025 %","40 %","6 %"],"ex":"6 ÷ 240 × 100 = 2.5 %.","ref":"Modul 1 · Prozentrechnen"},{"k":"tf","q":"Eine Erhöhung um 10 % und danach eine Senkung um 10 % ergeben genau wieder den Anfangspreis.","v":false,"ex":"Falsch: 100 × 1.1 = 110; 110 × 0.9 = 99. Die Senkung wird auf 110 berechnet, nicht auf 100.","ref":"Modul 1 · Prozentrechnen"},{"k":"order","q":"Bringen Sie die Berechnung einer Rechnung mit Rabatt und Transportkosten in die richtige Reihenfolge.","a":["Den Rabatt auf dem Anfangspreis berechnen","Den Rabatt vom Anfangspreis abziehen","Die Transportkosten dazuzählen","Prüfen, ob das Total plausibel ist"],"ex":"Der Rabatt gilt für den Warenpreis, bevor die Kosten dazukommen.","ref":"Modul 3 · Aufgaben Serie 2"},{"k":"sort","q":"Ordnen Sie jeden Faktor zu: Erhöhung oder Senkung?","c":["Erhöhung","Senkung"],"it":[["× 1.08",0],["× 0.85",1],["× 1.2",0],["× 0.97",1],["× 1.081",0],["× 0.5",1]],"ex":"Grösser als 1: Erhöhung (1.08 = + 8 %). Kleiner als 1: Senkung (0.85 = − 15 %).","ref":"Modul 1 · Prozentrechnen"},{"k":"odd","q":"Finden Sie den Ausreisser: Welcher Wert ist NICHT gleich 20 %?","a":["0.02","0.2","1/5","20/100"],"ex":"20 % = 20/100 = 0.2 = 1/5. 0.02 = 2 %.","ref":"Modul 1 · Prozentrechnen"},{"k":"case","s":"Ein Kunde fragt nach dem Preis inkl. MWST eines Artikels, der CHF 200.00 exkl. MWST kostet. Der Normalsatz der MWST in der Schweiz beträgt 8.1 %.","q":"Wie hoch ist der Preis inkl. MWST?","a":["CHF 216.20","CHF 215.40","CHF 208.10","CHF 183.80"],"ex":"Preis inkl. MWST = Preis exkl. MWST × (1 + Satz) = 200 × 1.081 = CHF 216.20. Nicht im Kursmaterial · Ergänzung: Der Kurs verwendet noch 7.7 %, der Normalsatz beträgt aber seit dem 1. Januar 2024 8.1 %.","ref":"Modul 3 · Aufgaben Serie 3"},{"k":"num","q":"Ein Lastwagen mit 24 Palettenplätzen ist zu 75 % gefüllt. Wie viele Paletten enthält er?","n":18,"tol":0,"u":"Paletten","ex":"24 × 75 ÷ 100 = 18 Paletten.","ref":"Modul 1 · Prozentrechnen"},{"k":"case","s":"Der Kartonlieferant kündigt auf den 1. Januar eine Erhöhung um 5 % an. Ein Posten kostete bisher CHF 80.00.","q":"Wie hoch wird der neue Preis des Postens sein?","a":["CHF 84.00","CHF 85.00","CHF 80.05","CHF 76.00"],"ex":"80 × 1.05 = CHF 84.00.","ref":"Modul 1 · Prozentrechnen"},{"k":"qcm","q":"Wie viel sind 18 % von 350?","a":["63","6.3","19.4","630"],"ex":"350 × 18 ÷ 100 = 63.","ref":"Modul 1 · Prozentrechnen"},{"k":"case","s":"Eine Rechnung von CHF 1’850.00 gewährt 2 % Skonto bei Zahlung innert 10 Tagen. Die Buchhaltung zahlt rechtzeitig.","q":"Welchen Betrag bezahlt sie?","a":["CHF 1’813.00","CHF 1’848.00","CHF 1’480.00","CHF 1’887.00"],"ex":"1’850 × 0.98 = CHF 1’813.00 (Skonto: CHF 37.00).","ref":"Modul 1 · Prozentrechnen"},{"k":"num","q":"90 Paletten sind 30 % des Bestands. Wie viele Paletten umfasst der ganze Bestand?","n":300,"tol":0,"u":"Paletten","ex":"Total = Anteil × 100 ÷ Prozentsatz = 90 × 100 ÷ 30 = 300 Paletten.","ref":"Modul 1 · Prozentrechnen"},{"k":"multi","q":"Welche Rechnungen ergeben den Preis nach 20 % Rabatt?","good":["Preis × 0.8","Preis − Preis × 0.2","Preis × 80 ÷ 100"],"bad":["Preis × 1.2","Preis − 20"],"ex":"20 % Rabatt: Es bleiben 80 % des Preises, also × 0.8.","ref":"Modul 1 · Prozentrechnen"},{"k":"case","s":"Von 500 Paketen, die der Transporteur letzten Monat geliefert hat, kamen 2 % beschädigt an. Der Verantwortliche bereitet die Reklamation vor.","q":"Wie viele Pakete sind beschädigt?","a":["10 Pakete","2 Pakete","25 Pakete","100 Pakete"],"ex":"500 × 2 ÷ 100 = 10 Pakete.","ref":"Modul 1 · Prozentrechnen"},{"k":"tf","q":"1 % von 1’000 kg sind 10 kg.","v":true,"ex":"Richtig: 1’000 × 1 ÷ 100 = 10 kg.","ref":"Modul 1 · Prozentrechnen"},{"k":"case","s":"Das Lager hat 800 Palettenplätze. Heute sind 640 belegt. Der Direktor will den Belegungsgrad.","q":"Wie hoch ist der Belegungsgrad?","a":["80 %","0.8 %","64 %","125 %"],"ex":"640 ÷ 800 × 100 = 80 %.","ref":"Modul 1 · Prozentrechnen"},{"k":"qcm","q":"Der Rechner zeigt 0.1 als Ergebnis eines Prozentsatzes. Wie viel Prozent sind das?","a":["10 %","1 %","0.1 %","100 %"],"ex":"0.1 × 100 = 10 %. Denken Sie daran, mit 100 zu multiplizieren, um das Ergebnis in % zu schreiben.","ref":"Modul 1 · Prozentrechnen"}]},{"code":"Mod. 2a","t":"Flächen und Volumen","g":"Nützliche Flächen und Volumen im Lager berechnen und umrechnen","col":"coral","ic":"cube","ch":[{"k":"qcm","q":"Welche Formel ergibt die Fläche eines Rechtecks?","a":["Länge × Breite","Länge + Breite","2 × (Länge + Breite)","Länge ÷ Breite"],"ex":"Fläche = L × B. 2 × (L + B) ergibt den Umfang, nicht die Fläche.","ref":"Modul 2 · Flächen berechnen"},{"k":"num","q":"Wie gross ist die Fläche eines Lagers von 50 m auf 24 m?","n":1200,"tol":0,"u":"m²","ex":"50 × 24 = 1’200 m².","ref":"Modul 2 · Flächen berechnen"},{"k":"qcm","q":"Welche Bodenfläche belegt eine EUR-Palette von 1.2 m × 0.8 m?","a":["0.96 m²","9.60 m²","2.00 m²","4.00 m²"],"ex":"1.2 × 0.8 = 0.96 m².","ref":"Modul 2 · Flächen berechnen"},{"k":"case","s":"Der Verantwortliche der Stockalp AG bereitet eine Zone für 20 EUR-Paletten (1.2 m × 0.8 m) vor, flach abgestellt, ohne Stapeln und ohne Gänge.","q":"Welche Fläche braucht es mindestens?","a":["19.2 m²","20 m²","40 m²","1.92 m²"],"ex":"1 Palette: 0.96 m². 20 × 0.96 = 19.2 m².","ref":"Modul 2 · Flächen berechnen"},{"k":"num","q":"Wie viele dm² hat 1 m²?","n":100,"tol":0,"u":"dm²","ex":"Bei Flächen ist jeder Schritt der Tabelle × 100: 1 m² = 100 dm².","ref":"Modul 2 · Flächen berechnen"},{"k":"num","q":"Rechnen Sie 3.2 m² in cm² um.","n":32000,"tol":0,"u":"cm²","ex":"m² → cm² = 2 Schritte: 3.2 × 100 × 100 = 32’000 cm².","ref":"Modul 2 · Flächen berechnen"},{"k":"qcm","q":"Rechnen Sie 45’000 mm² in m² um.","a":["0.045 m²","0.450 m²","0.0045 m²","4.500 m²"],"ex":"mm² → m² = 3 Schritte nach links: 45’000 ÷ 100 ÷ 100 ÷ 100 = 0.045 m². Achtung: Das Beispiel im Kurs nennt 0.45 m², das ist ein Fehler.","ref":"Modul 2 · Flächen berechnen"},{"k":"tf","q":"In der Flächentabelle ist jeder Schritt von einer Einheit zur nächsten × 100 oder ÷ 100.","v":true,"ex":"Richtig: 1 m² = 100 dm² = 10’000 cm². Bei Längen ist es × 10, bei Volumen × 1’000.","ref":"Modul 2 · Flächen berechnen"},{"k":"tf","q":"In der Volumentabelle ist jeder Schritt von einer Einheit zur nächsten × 1’000’000’000.","v":false,"ex":"Falsch: Jeder Schritt ist × 1’000 (1 m³ = 1’000 dm³). Der «Tipp» im Kurs mit 1 Milliarde pro Schritt ist ein Fehler.","ref":"Modul 2 · Volumen berechnen"},{"k":"num","q":"Wie viele Liter fasst 1 m³?","n":1000,"tol":0,"u":"L","ex":"1 m³ = 1’000 dm³ und 1 dm³ = 1 L, also 1 m³ = 1’000 L.","ref":"Modul 2 · Volumen berechnen"},{"k":"num","q":"Rechnen Sie 2.5 m³ in Liter um.","n":2500,"tol":0,"u":"L","ex":"2.5 × 1’000 = 2’500 L.","ref":"Modul 2 · Volumen berechnen"},{"k":"qcm","q":"Rechnen Sie 4’800 cm³ in Liter um.","a":["4.8 L","48 L","0.48 L","480 L"],"ex":"4’800 cm³ ÷ 1’000 = 4.8 dm³ = 4.8 L.","ref":"Modul 2 · Volumen berechnen"},{"k":"case","s":"Der Spediteur muss das Nutzvolumen eines Containers melden, der innen 6 m lang, 2.5 m breit und 2.7 m hoch ist.","q":"Welches Volumen meldet er?","a":["40.5 m³","11.2 m³","15.0 m³","405 m³"],"ex":"V = 6 × 2.5 × 2.7 = 40.5 m³.","ref":"Modul 2 · Volumen berechnen"},{"k":"case","s":"Fässer zu 210 L müssen in einem Lagerraum von 2.5 m³ untergebracht werden. Man zählt nur das Volumen, und ein Fass wird nicht geteilt.","q":"Wie viele ganze Fässer passen höchstens hinein?","a":["11 Fässer","12 Fässer","84 Fässer","1 Fass"],"ex":"2.5 m³ = 2’500 L. 2’500 ÷ 210 = 11.9 → man rundet ab: 11 Fässer.","ref":"Modul 2 · Volumen berechnen"},{"k":"case","img":"zone","s":"Eine Lagerzone misst 6 m auf 4 m. Man stellt EUR-Paletten von 1.2 m × 0.8 m darauf, alle in derselben Richtung, ohne Gang.","q":"Wie viele Paletten kann man auf den Boden stellen?","a":["25 Paletten","24 Paletten","30 Paletten","20 Paletten"],"ex":"6 ÷ 1.2 = 5 Paletten auf der Länge; 4 ÷ 0.8 = 5 auf der Breite. 5 × 5 = 25 Paletten (24 m² ÷ 0.96 m² = 25 ebenfalls).","ref":"Modul 2 · Flächen berechnen"},{"k":"num","q":"Wie viele Kartons zu 0.05 m³ kann man in 15 m³ lagern (nur das Volumen gezählt)?","n":300,"tol":0,"u":"Kartons","ex":"15 ÷ 0.05 = 300 Kartons.","ref":"Modul 2 · Volumen berechnen"},{"k":"qcm","q":"Wie gross ist das Volumen einer beladenen Palette von 1.2 m × 0.8 m × 1.7 m?","a":["1.632 m³","3.7 m³","0.96 m³","16.32 m³"],"ex":"1.2 × 0.8 × 1.7 = 1.632 m³.","ref":"Modul 2 · Volumen berechnen"},{"k":"match","q":"Ordnen Sie jeder Einheit ihre Entsprechung zu.","p":[["1 m²","100 dm²"],["1 m³","1’000 L"],["1 L","1 dm³"],["1 cm²","100 mm²"]],"ex":"Flächen: × 100 pro Schritt. Volumen: × 1’000 pro Schritt. 1 L = 1 dm³.","ref":"Modul 2 · Volumen berechnen"},{"k":"sort","q":"Ordnen Sie zu: Fläche oder Volumen?","c":["Fläche","Volumen"],"it":[["m²",0],["m³",1],["L",1],["cm²",0],["Bodenfläche einer Palette",0],["Fassungsvermögen eines Tanks",1]],"ex":"Fläche: 2 Dimensionen (m², cm²). Volumen: 3 Dimensionen (m³, L).","ref":"Modul 2 · Flächen berechnen"},{"k":"order","q":"Ordnen Sie diese Flächeneinheiten von der grössten zur kleinsten.","a":["km²","dam²","m²","cm²","mm²"],"ex":"km², hm², dam², m², dm², cm², mm².","ref":"Modul 2 · Flächen berechnen"},{"k":"odd","q":"Finden Sie den Ausreisser: Welche ist KEINE Volumeneinheit?","a":["m²","m³","L","dm³"],"ex":"m² misst eine Fläche. m³, L und dm³ messen ein Volumen.","ref":"Modul 2 · Volumen berechnen"},{"k":"case","s":"Eine beladene Palette hat ein Volumen von 1.44 m³ und belegt 0.96 m² Boden. Der Lagerist will ihre Höhe kennen, um einen Lagerplatz zu wählen.","q":"Wie hoch ist sie?","a":["1.5 m","1.38 m","2.4 m","0.67 m"],"ex":"Höhe = Volumen ÷ Fläche = 1.44 ÷ 0.96 = 1.5 m.","ref":"Modul 3 · Aufgaben Serie 1"},{"k":"case","s":"Ein Palettenregal ist 1.2 m tief und 12 m lang. Der Verantwortliche will wissen, welche Bodenfläche es belegt.","q":"Welche Fläche belegt es?","a":["14.4 m²","13.2 m²","26.4 m²","1.44 m²"],"ex":"1.2 × 12 = 14.4 m².","ref":"Modul 2 · Flächen berechnen"},{"k":"case","s":"Eine Zone hat 12 m² Bodenfläche und ist 2.2 m hoch. Man will 9 Paletten von 0.96 m² und 1.67 m Höhe lagern, je 2 aufeinander gestapelt.","q":"Was antworten Sie?","a":["Nicht gestapelt, aber am Boden haben alle 9 Platz","Ja: 5 gestapelte Lagerplätze genügen","Nein: Die 9 Paletten haben keinen Platz","Ja, wenn man sie zu dritt stapelt"],"ex":"Gestapelt: 2 × 1.67 = 3.34 m > 2.2 m, unmöglich. Am Boden: 9 × 0.96 = 8.64 m² ≤ 12 m², das ist möglich.","ref":"Modul 3 · Aufgaben Serie 1"},{"k":"num","q":"Eine Fläche von 600 m² wird in 3 gleiche Zonen aufgeteilt. Wie gross ist eine Zone?","n":200,"tol":0,"u":"m²","ex":"600 ÷ 3 = 200 m².","ref":"Modul 2 · Flächen berechnen"},{"k":"multi","q":"Welche Werte sind gleich 1.5 m³?","good":["1’500 L","1’500 dm³","1’500’000 cm³"],"bad":["150 L","15’000 cm³"],"ex":"1.5 m³ = 1’500 dm³ = 1’500 L = 1’500’000 cm³.","ref":"Modul 2 · Volumen berechnen"},{"k":"case","s":"Der Auflieger eines Sattelzugs ist innen 13.6 m lang, 2.45 m breit und 2.7 m hoch. Der Disponent will das Ladevolumen.","q":"Wie gross ist dieses Volumen?","a":["89.96 m³","33.32 m³","18.75 m³","899.64 m³"],"ex":"13.6 × 2.45 × 2.7 = 89.96 m³ (etwa 90 m³).","ref":"Modul 2 · Volumen berechnen"},{"k":"case","s":"Ein Karton misst 60 cm × 40 cm × 50 cm. Der Transporteur verrechnet nach Volumen und verlangt den Wert in m³.","q":"Welches Volumen melden Sie?","a":["0.12 m³","120 m³","1.2 m³","0.012 m³"],"ex":"Zuerst in Meter umrechnen: 0.6 × 0.4 × 0.5 = 0.12 m³ (= 120’000 cm³).","ref":"Modul 2 · Volumen berechnen"}]},{"code":"Mod. 2b","t":"Zeit, Strecken und Geschwindigkeiten","g":"Dauern, Ankunftszeiten, Strecken und Geschwindigkeiten berechnen","col":"amber","ic":"clock2","ch":[{"k":"num","q":"Wie viele Minuten sind 1 h 30?","n":90,"tol":0,"u":"min","ex":"1 h = 60 min. 60 + 30 = 90 min.","ref":"Modul 2 · Arbeitszeit"},{"k":"qcm","q":"Wie viele Stunden (als Dezimalzahl) sind 90 Minuten?","a":["1.5 h","1.3 h","1.9 h","0.9 h"],"ex":"Minuten → Stunden: ÷ 60. 90 ÷ 60 = 1.5 h.","ref":"Modul 2 · Arbeitszeit"},{"k":"qcm","q":"Welcher Dauer entsprechen 2.25 h?","a":["2 h 15","2 h 25","2 h 02","2 h 30"],"ex":"0.25 h × 60 = 15 min. 2.25 h = 2 h 15.","ref":"Modul 2 · Arbeitszeit"},{"k":"num","q":"Wie viele Sekunden sind 4 min 30 s?","n":270,"tol":0,"u":"s","ex":"4 × 60 + 30 = 270 s.","ref":"Modul 2 · Arbeitszeit"},{"k":"case","s":"Ein Chauffeur von Livrex fährt um 08:45 im Depot ab, für eine geplante Tour von 2 h 35.","q":"Wann muss er zurück sein?","a":["11:20","10:80","11:30","10:20"],"ex":"Stunden: 8 + 2 = 10 h. Minuten: 45 + 35 = 80 min = 1 h 20. 10 h + 1 h 20 = 11:20.","ref":"Modul 2 · Arbeitszeit"},{"k":"qcm","q":"Welche Dauer liegt zwischen 14:10 und 17:40?","a":["3 h 30","3 h 50","4 h 30","3 h 20"],"ex":"Von 14:10 bis 17:10: 3 h. Plus 30 min: 3 h 30.","ref":"Modul 2 · Arbeitszeit"},{"k":"case","s":"Ein Lagerist arbeitet von 07:30 bis 11:45 und von 13:15 bis 17:00. Er muss seinen Stundenzettel ausfüllen.","q":"Wie viele Stunden hat er gearbeitet?","a":["8 h","7 h 45","9 h 30","8 h 15"],"ex":"Morgen: 4 h 15. Nachmittag: 3 h 45. Total: 8 h.","ref":"Modul 2 · Arbeitszeit"},{"k":"case","s":"Ein Kommissionierer braucht 12 Minuten, um eine Palette zu folieren und zu etikettieren. Bis zur Abfahrt des Lastwagens muss er 15 Paletten bereitstellen.","q":"Wie viel Zeit braucht er?","a":["3 h","2 h 30","1 h 80","2 h 45"],"ex":"15 × 12 = 180 min = 3 h.","ref":"Modul 2 · Arbeitszeit"},{"k":"num","q":"Ein Arbeitsgang dauert 3 min 20 s. Wie oft kann man ihn in 1 Stunde ausführen?","n":18,"tol":0,"u":"Mal","ex":"3 min 20 s = 200 s. 1 h = 3’600 s. 3’600 ÷ 200 = 18-mal.","ref":"Modul 2 · Arbeitszeit"},{"k":"case","s":"An einem Arbeitstag von 8 h macht ein Mitarbeiter 40 min Pause und ist 1 h an einer Teamsitzung. Der Chef will seine produktive Zeit kennen.","q":"Wie gross ist seine produktive Zeit?","a":["6 h 20","7 h","6 h 40","7 h 20"],"ex":"8 h − 40 min − 1 h = 6 h 20.","ref":"Modul 2 · Arbeitszeit"},{"k":"case","s":"Eine Tour beginnt um 06:10 und dauert 3 h 45. Danach isst der Chauffeur 40 min und fährt dann noch 1 h 30 für Lieferungen.","q":"Wann ist er fertig?","a":["12:05","11:05","11:25","10:35"],"ex":"06:10 + 3 h 45 = 09:55; + 40 min = 10:35; + 1 h 30 = 12:05. Das Quiz im Kurs nennt 11:05, das ist ein Fehler.","ref":"Modul 2 · Arbeitszeit"},{"k":"qcm","q":"Mit welcher Formel berechnet man eine Strecke?","a":["D = V × T","D = V ÷ T","D = T ÷ V","D = V + T"],"ex":"Strecke = Geschwindigkeit × Zeit. Geschwindigkeit = D ÷ T; Zeit = D ÷ V.","ref":"Modul 2 · Strecken und Geschwindigkeiten"},{"k":"num","q":"Eine Fahrt von 360 km dauert 4 h. Wie hoch ist die Durchschnittsgeschwindigkeit?","n":90,"tol":0,"u":"km/h","ex":"V = 360 ÷ 4 = 90 km/h.","ref":"Modul 2 · Strecken und Geschwindigkeiten"},{"k":"num","q":"Ein Auslieferer fährt 45 Minuten lang mit 80 km/h. Welche Strecke legt er zurück?","n":60,"tol":0,"u":"km","ex":"45 min = 0.75 h. 80 × 0.75 = 60 km.","ref":"Modul 2 · Strecken und Geschwindigkeiten"},{"k":"num","q":"Wie viele Stunden braucht man für 200 km mit 100 km/h?","n":2,"tol":0,"u":"h","ex":"T = 200 ÷ 100 = 2 h.","ref":"Modul 2 · Strecken und Geschwindigkeiten"},{"k":"case","s":"Ein Auslieferer fährt zuerst 60 Minuten mit 45 km/h in der Stadt, dann 90 Minuten mit 60 km/h auf der Kantonsstrasse.","q":"Welche Strecke hat er zurückgelegt?","a":["135 km","127.5 km","105 km","157.5 km"],"ex":"45 × 1 = 45 km; 60 × 1.5 = 90 km. Total: 135 km. Das Quiz im Kurs nennt 127.5 km, das ist ein Fehler.","ref":"Modul 2 · Strecken und Geschwindigkeiten"},{"k":"case","s":"Ein Lastwagen fährt 180 km in 2 h, macht 30 min Pause und fährt dann noch 120 km mit 60 km/h.","q":"Wie lange dauert es insgesamt?","a":["4 h 30","5 h 30","4 h 00","5 h 00"],"ex":"2 h + 30 min + (120 ÷ 60 = 2 h) = 4 h 30. Das Quiz im Kurs nennt 5 h 30, das ist ein Fehler.","ref":"Modul 2 · Strecken und Geschwindigkeiten"},{"k":"case","s":"Ein Chauffeur fährt um 07:40 ab, für eine Fahrt von 192 km. Er fährt mit einer Durchschnittsgeschwindigkeit von 80 km/h, ohne Pause.","q":"Wann kommt er an?","a":["10:04","10:32","09:52","10:24"],"ex":"T = 192 ÷ 80 = 2.4 h = 2 h 24 (0.4 × 60 = 24 min). 07:40 + 2 h 24 = 10:04.","ref":"Modul 2 · Strecken und Geschwindigkeiten"},{"k":"qcm","q":"Wie vielen Stunden als Dezimalzahl entsprechen 1 h 20 min?","a":["1.33 h","1.20 h","1.50 h","1.25 h"],"ex":"20 min ÷ 60 = 0.33 h. 1 h 20 = 1.33 h, nicht 1.20 h.","ref":"Modul 2 · Strecken und Geschwindigkeiten"},{"k":"qcm","q":"Ein Auslieferer braucht 1 h 20 für 96 km. Wie hoch ist seine Durchschnittsgeschwindigkeit?","a":["72 km/h","80 km/h","76.8 km/h","120 km/h"],"ex":"1 h 20 = 4/3 h. V = 96 ÷ 4/3 = 96 × 3 ÷ 4 = 72 km/h.","ref":"Modul 2 · Strecken und Geschwindigkeiten"},{"k":"case","s":"Im Lager misst man die Zeit eines Gabelstaplers: Er legt 600 m in 3 Minuten zurück. Der Sicherheitsverantwortliche will seine Geschwindigkeit in km/h.","q":"Wie schnell fährt der Stapler?","a":["12 km/h","200 km/h","20 km/h","1.8 km/h"],"ex":"600 m = 0.6 km ; 3 min = 0.05 h. V = 0.6 ÷ 0.05 = 12 km/h.","ref":"Modul 2 · Strecken und Geschwindigkeiten"},{"k":"match","q":"Ordnen Sie jeder Umrechnung die passende Rechnung zu.","p":[["min → h","÷ 60"],["h → min","× 60"],["m/s → km/h","× 3.6"],["km → m","× 1’000"]],"ex":"Tabelle der nützlichen Umrechnungen aus dem Kurs.","ref":"Modul 2 · Strecken und Geschwindigkeiten"},{"k":"order","q":"Bringen Sie die Methode zum Addieren von zwei Dauern in die richtige Reihenfolge.","a":["Die Stunden zusammenzählen","Die Minuten zusammenzählen","Minuten über 60 in Stunden umrechnen","Das Ergebnis in h und min schreiben"],"ex":"1 h 45 + 2 h 35 = 3 h 80 min = 4 h 20.","ref":"Modul 2 · Arbeitszeit"},{"k":"sort","q":"Ordnen Sie zu: Dauer oder Uhrzeit (Zeitpunkt)?","c":["Dauer","Uhrzeit"],"it":[["Abfahrt um 07:40",1],["Fahrt von 2 h 24",0],["Pause von 30 min",0],["Ankunft um 10:04",1],["Tour von 5 h 40",0],["Dienstende um 17:00",1]],"ex":"Eine Uhrzeit gibt einen Zeitpunkt an; eine Dauer gibt an, wie viel Zeit vergeht.","ref":"Modul 2 · Arbeitszeit"},{"k":"odd","q":"Finden Sie den Ausreisser: Welche Dauer ist NICHT gleich 2.5 h?","a":["2 h 50","2 h 30","150 min","9’000 s"],"ex":"2.5 h = 2 h 30 = 150 min = 9’000 s. 2 h 50 = 2.83 h.","ref":"Modul 2 · Arbeitszeit"},{"k":"tf","q":"2 h 30 schreibt man als Dezimalzahl 2.30 h.","v":false,"ex":"Falsch: 30 min = 0.5 h, also 2 h 30 = 2.5 h. Eine Stunde hat 60 Minuten, nicht 100.","ref":"Modul 2 · Arbeitszeit"},{"k":"case","s":"Ein Schlepper fährt im Lager mit 4.5 km/h. Der Fahrer ist auf seiner Versorgungstour insgesamt 40 Minuten damit unterwegs.","q":"Welche Strecke legt er zurück?","a":["3 km","180 km","1.8 km","4.5 km"],"ex":"40 min = 2/3 h. 4.5 × 2/3 = 3 km.","ref":"Modul 2 · Strecken und Geschwindigkeiten"},{"k":"case","s":"Ein Lastwagen fährt 100 km mit 50 km/h, dann 60 km mit 80 km/h, dann 90 km mit 60 km/h. Der Disponent berechnet die Fahrzeit.","q":"Wie lange ist die gesamte Fahrzeit?","a":["4 h 15","4 h","3 h 45","4 h 30"],"ex":"100 ÷ 50 = 2 h; 60 ÷ 80 = 45 min; 90 ÷ 60 = 1 h 30. Total: 4 h 15.","ref":"Modul 2 · Strecken und Geschwindigkeiten"},{"k":"tf","q":"Um eine Geschwindigkeit von m/s in km/h umzurechnen, multipliziert man mit 3.6.","v":true,"ex":"Richtig: 1 m/s = 3.6 km/h (3’600 s in 1 h, 1’000 m in 1 km).","ref":"Modul 2 · Strecken und Geschwindigkeiten"},{"k":"num","q":"Rechnen Sie 10 m/s in km/h um.","n":36,"tol":0,"u":"km/h","ex":"10 × 3.6 = 36 km/h.","ref":"Modul 2 · Strecken und Geschwindigkeiten"},{"k":"case","s":"Ein Auslieferer muss um 14:00 beim Kunden sein. Die Fahrt beträgt 150 km und er fährt im Durchschnitt 75 km/h, ohne Pause.","q":"Wann muss er spätestens abfahren?","a":["12:00","12:30","11:45","13:15"],"ex":"T = 150 ÷ 75 = 2 h. 14:00 − 2 h = 12:00.","ref":"Modul 2 · Strecken und Geschwindigkeiten"}]},{"code":"Mod. 3","t":"Aufgaben in mehreren Schritten","g":"Eine Logistikaufgabe in mehreren Schritten lösen und prüfen, ob das Ergebnis realistisch ist","col":"emerald","ic":"steps","ch":[{"k":"order","q":"Bringen Sie die Methode zum Lösen einer Aufgabe in mehreren Schritten in die richtige Reihenfolge.","a":["Die Aufgabe aufmerksam lesen","Die Daten erkennen und die Einheiten umrechnen","Schritt für Schritt rechnen","Prüfen, ob das Ergebnis stimmig ist"],"ex":"Methode des Kurses: lesen, zerlegen, Schritt für Schritt rechnen, dann prüfen, ob die Antwort realistisch ist.","ref":"Modul 3 · Aufgaben Serie 1"},{"k":"case","s":"Neun Paletten werden im Block gelagert, je 2 aufeinander. Jeder Stapel belegt einen Platz am Boden.","q":"Wie viele Lagerplätze braucht es?","a":["5 Lagerplätze","4 Lagerplätze","4.5 Lagerplätze","9 Lagerplätze"],"ex":"9 ÷ 2 = 4.5 → man rundet auf: 4 Stapel zu 2 + 1 einzelne Palette = 5 Lagerplätze.","ref":"Modul 3 · Aufgaben Serie 1"},{"k":"case","s":"Ein Auftrag von 180 Paketen wird palettiert. Pro Palette kommen höchstens 24 Pakete.","q":"Wie viele Paletten muss man bereitstellen?","a":["8 Paletten","7 Paletten","7.5 Paletten","9 Paletten"],"ex":"180 ÷ 24 = 7.5 → man rundet auf: 8 Paletten (die letzte ist nicht voll).","ref":"Modul 3 · Aufgaben Serie 1"},{"k":"case","s":"Ein Lieferwagen hat eine Nutzlast von 1.5 t. Man lädt 480 kg Kartons, 0.65 t Kanister und 3’500 hg Säcke.","q":"Wird die Nutzlast eingehalten?","a":["Ja: 1’480 kg, es bleiben 20 kg","Nein: 1’480 kg überschreiten 1.5 t","Nein: 4’630 kg überschreiten 1.5 t","Ja: 1’130 kg, es bleiben 370 kg"],"ex":"Alles in kg: 480 + 650 + 350 = 1’480 kg ≤ 1’500 kg. Es bleiben 20 kg.","ref":"Modul 3 · Aufgaben Serie 2"},{"k":"case","s":"Ein Regal trägt 1’000 kg. Man will 20 Kartons zu 18 kg, 15 Kartons zu 25 kg und 8 Kartons zu 40 kg darauf lagern.","q":"Was stellen Sie fest?","a":["Überlast von 55 kg","Es bleiben 55 kg Reserve","Überlast von 83 kg","Die Last beträgt genau 1’000 kg"],"ex":"360 + 375 + 320 = 1’055 kg > 1’000 kg: Überlast von 55 kg. Kartons müssen umgelagert werden.","ref":"Modul 3 · Aufgaben Serie 2"},{"k":"num","img":"tournee","q":"Eine Tour beliefert 5 Kunden: 22 km, 13 km, 8 km, 14 km und 18 km zwischen den Halten, dann 25 km direkt zurück ins Depot. Gesamtstrecke?","n":100,"tol":0,"u":"km","ex":"Hinweg: 22 + 13 + 8 + 14 + 18 = 75 km. Mit der Rückfahrt: 75 + 25 = 100 km.","ref":"Modul 3 · Aufgaben Serie 2"},{"k":"case","s":"Eine Bestellung von Regalen kostet CHF 4’500.00. Der Lieferant gewährt 8 % Rabatt und verrechnet CHF 95.00 für die Lieferung.","q":"Wie hoch ist der Rechnungsbetrag?","a":["CHF 4’235.00","CHF 4’227.40","CHF 4’140.00","CHF 4’955.00"],"ex":"4’500 × 0.92 = 4’140; 4’140 + 95 = CHF 4’235.00. Der Rabatt gilt nicht für die Lieferkosten.","ref":"Modul 3 · Aufgaben Serie 2"},{"k":"case","s":"Ein Kommissionierer muss 5 Pakete vom Typ A (je 7 min), 8 vom Typ B (12 min) und 4 vom Typ C (9 min) bereitstellen.","q":"Wie viel Zeit braucht er insgesamt?","a":["2 h 47","2 h 30","1 h 67","3 h 07"],"ex":"35 + 96 + 36 = 167 min = 2 h 47.","ref":"Modul 3 · Aufgaben Serie 3"},{"k":"case","s":"Sie verrechnen 12 Stück zu CHF 48.00 exkl. MWST. Die MWST zum Normalsatz (8.1 %) muss dazugerechnet werden.","q":"Wie hoch ist das Total inkl. MWST?","a":["CHF 622.66","CHF 620.35","CHF 584.10","CHF 529.34"],"ex":"12 × 48 = CHF 576.00 exkl. MWST. 576 × 1.081 = CHF 622.66. Nicht im Kursmaterial · Ergänzung: Der Kurs rechnet mit 7.7 %, dem Satz bis Ende 2023.","ref":"Modul 3 · Aufgaben Serie 3"},{"k":"case","s":"Eine Palette von 720 kg muss abgeladen und in kleineren Lasten mit einem Transportwagen bewegt werden, der höchstens 300 kg trägt.","q":"Wie viele Fahrten braucht es?","a":["3 Fahrten","2 Fahrten","2.4 Fahrten","4 Fahrten"],"ex":"720 ÷ 300 = 2.4 → man rundet auf: 3 Fahrten.","ref":"Modul 3 · Aufgaben Serie 4"},{"k":"case","s":"Ein Auftrag umfasst 4 Kartons zu 5 kg, 6 Kartons zu 7.5 kg und 6 Kartons zu 2.8 kg. Er kommt auf einen Fachboden, der 100 kg trägt.","q":"Kann man ihn auf diesem Fachboden lagern?","a":["Ja: 81.8 kg, Reserve von 18.2 kg","Nein: 81.8 kg überschreiten 100 kg","Ja: nur 15.3 kg","Nein: 109.4 kg überschreiten 100 kg"],"ex":"20 + 45 + 16.8 = 81.8 kg ≤ 100 kg. Reserve: 18.2 kg.","ref":"Modul 3 · Aufgaben Serie 4"},{"k":"case","s":"Ein Chauffeur hat 6 h für eine Tour von 240 km mit durchschnittlich 80 km/h, mit 12 Lieferungen zu 10 min und 3 Pausen zu 15 min.","q":"Hält er die Frist ein?","a":["Ja: 5 h 45, Reserve von 15 min","Nein: 6 h 15, Verspätung von 15 min","Ja: nur 3 h Fahrt","Nein: 6 h 45, Verspätung von 45 min"],"ex":"Fahrt: 240 ÷ 80 = 3 h. Lieferungen: 2 h. Pausen: 45 min. Total: 5 h 45 ≤ 6 h.","ref":"Modul 3 · Aufgaben Serie 4"},{"k":"case","img":"zone","s":"Eine Zone von 6 m × 4 m und 2.5 m Höhe soll EUR-Paletten von 1.5 m Höhe aufnehmen. Der Chef fragt nach der Kapazität der Zone.","q":"Wie viele Paletten fasst die Zone?","a":["25 Paletten, in nur 1 Lage","50 Paletten, in 2 Lagen","24 Paletten, in nur 1 Lage","41 Paletten, in 2 Lagen"],"ex":"Am Boden: 5 × 5 = 25 Paletten. In der Höhe: 2 × 1.5 = 3 m > 2.5 m, also nur eine Lage.","ref":"Modul 3 · Aufgaben Serie 3"},{"k":"tf","q":"Bei der Anzahl Fahrten rundet man immer auf die nächste ganze Zahl auf.","v":true,"ex":"Richtig: Bei 2.4 Fahrten bleibt noch eine Last übrig, es braucht also eine 3. Fahrt.","ref":"Modul 3 · Aufgaben Serie 4"},{"k":"tf","q":"Um zu wissen, wie viele ganze Fässer in einen Raum passen, rundet man auf.","v":false,"ex":"Falsch: Das 12. Fass hätte keinen Platz. Wenn man sucht, was «hineinpasst», rundet man ab.","ref":"Modul 2 · Volumen berechnen"},{"k":"sort","q":"Muss man aufrunden oder abrunden?","c":["Aufrunden","Abrunden"],"it":[["Anzahl nötiger Fahrten",0],["Paletten für 180 Pakete",0],["Fässer, die in 2.5 m³ passen",1],["In 50 min bereitgestellte Pakete",1],["Einzustellende Personen",0],["Kartons auf einem Fachboden mit Lastgrenze",1]],"ex":"Was man braucht, um alles zu erledigen: aufrunden. Was hineinpasst oder fertig ist: abrunden.","ref":"Modul 3 · Aufgaben Serie 4"},{"k":"match","q":"Ordnen Sie jeder Grösse ihre Formel zu.","p":[["Preis nach Rabatt","Preis × (1 − Satz)"],["Preis inkl. MWST","Preis exkl. MWST × (1 + MWST-Satz)"],["Restkapazität","Max. Kapazität − genutzte Masse"],["Anzahl Fahrten","Gesamtmasse ÷ Kapazität"]],"ex":"Formeln der Aufgabenserien 2, 3 und 4.","ref":"Modul 3 · Aufgaben Serie 2"},{"k":"odd","q":"Finden Sie den Ausreisser: Welche Gewohnheit gehört NICHT zu einer guten Methode?","a":["Jedes Zwischenergebnis runden","Die nützlichen Daten erkennen","Die Werte in dieselbe Einheit bringen","Prüfen, ob die Antwort realistisch ist"],"ex":"Man behält die genauen Werte während der Rechnung und rundet nur das Endergebnis.","ref":"Modul 3 · Aufgaben Serie 1"},{"k":"num","q":"Man muss 4’250 kg mit einem Lieferwagen von 1’200 kg Nutzlast ausliefern. Wie viele Fahrten braucht es?","n":4,"tol":0,"u":"Fahrten","ex":"4’250 ÷ 1’200 = 3.54 → man rundet auf: 4 Fahrten.","ref":"Modul 3 · Aufgaben Serie 4"},{"k":"case","s":"Man will 8 EUR-Paletten (je 0.96 m²) flach in eine freie Ecke der Rampe von 7.5 m² stellen.","q":"Ist die Ecke gross genug?","a":["Nein: Es braucht 7.68 m²","Ja: Es braucht 7.2 m²","Ja: Es bleiben 0.18 m²","Nein: Es braucht 9.6 m²"],"ex":"8 × 0.96 = 7.68 m² > 7.5 m²: Es fehlen 0.18 m².","ref":"Modul 3 · Aufgaben Serie 1"},{"k":"case","s":"Eine beladene Palette hat 1.6 m³ auf 0.96 m² Bodenfläche. Der Lagerist möchte zwei davon unter einer Decke von 2.2 m stapeln.","q":"Ist das möglich?","a":["Nein: 2 × 1.67 m = 3.33 m","Ja: 1.67 m < 2.2 m","Ja: 1.6 m³ < 2.2 m","Nein: 2 × 0.96 m = 1.92 m"],"ex":"Höhe = 1.6 ÷ 0.96 ≈ 1.67 m. Zwei Paletten: etwa 3.33 m > 2.2 m.","ref":"Modul 3 · Aufgaben Serie 1"},{"k":"multi","q":"Welche Plausibilitätskontrollen sind am Ende einer Aufgabe nützlich?","good":["Eine Anzahl Paletten ist eine ganze Zahl","Die Masse überschreitet die Nutzlast nicht","Die Einheiten waren vor dem Addieren gleich"],"bad":["Das Ergebnis hat möglichst viele Dezimalstellen","Das Ergebnis ist grösser als alle Daten"],"ex":"Das Ergebnis muss realistisch sein und die Vorgaben vor Ort einhalten.","ref":"Modul 3 · Aufgaben Serie 1"},{"k":"case","s":"Ein Kollege zählt seine Bereitstellungszeiten zusammen: 35 + 96 + 36 = 167 min. Er schreibt «1 h 67» auf das Arbeitsblatt.","q":"Was korrigieren Sie?","a":["167 min = 2 h 47","167 min = 1.67 h","Nichts: 1 h 67 stimmt","167 min = 16 h 7"],"ex":"167 ÷ 60 = 2 Rest 47: 2 h 47. Eine Stunde hat 60 Minuten.","ref":"Modul 3 · Aufgaben Serie 3"},{"k":"case","s":"Ein Lager hat 3 Zonen zu 500 m². Gänge und Sicherheitszonen belegen 20 % der Fläche. Der Rest dient dazu, EUR-Paletten am Boden zu lagern.","q":"Wie viele Paletten höchstens am Boden?","a":["1’250 Paletten","1’562 Paletten","1’200 Paletten","1’440 Paletten"],"ex":"Total: 1’500 m². Lagerfläche: 1’500 × 0.8 = 1’200 m². 1’200 ÷ 0.96 = 1’250 Paletten (theoretisches Maximum).","ref":"Modul 3 · Aufgaben Serie 1"},{"k":"case","s":"Sie verrechnen 150 Kartons zu CHF 3.20 exkl. MWST. Der Kunde erhält 5 % Rabatt, danach kommt die MWST von 8.1 % dazu.","q":"Wie hoch ist das Total inkl. MWST?","a":["CHF 492.94","CHF 518.88","CHF 456.00","CHF 494.88"],"ex":"150 × 3.20 = 480; Rabatt: 480 × 0.95 = 456; MWST: 456 × 1.081 = CHF 492.94.","ref":"Modul 3 · Aufgaben Serie 3"},{"k":"num","q":"Ein Mitarbeiter stellt nur Pakete vom Typ C bereit (je 9 min). Wie viele schafft er in 90 min?","n":10,"tol":0,"u":"Pakete","ex":"90 ÷ 9 = 10 Pakete.","ref":"Modul 3 · Aufgaben Serie 3"},{"k":"case","s":"Abfahrt im Depot um 07:30. Die Tour umfasst 2 h 10 Fahrt, 7 Lieferungen zu 12 min und eine Pause von 20 min.","q":"Wann kehrt der Chauffeur zurück?","a":["11:24","10:04","11:44","10:24"],"ex":"7 × 12 = 84 min. 130 + 84 + 20 = 234 min = 3 h 54. 07:30 + 3 h 54 = 11:24.","ref":"Modul 3 · Aufgaben Serie 4"},{"k":"qcm","q":"Eine Rechnung enthält einen Rabatt und Transportkosten. In welcher Reihenfolge rechnet man?","a":["Zuerst der Rabatt, dann die Kosten","Zuerst die Kosten, dann der Rabatt","Rabatt nur auf die Kosten","Die Reihenfolge ändert nie etwas"],"ex":"Der Rabatt betrifft die Ware. Danach zählt man die Kosten dazu (Regel der Serie 2 im Kurs).","ref":"Modul 3 · Aufgaben Serie 2"}]}];
